import React from "react";
import "./Css.css";

const Css = () => {
    return (
        <div className="css-page">
            <h1>CSS Cheat Sheet</h1>

            <div className="css-grid">

                <div className="css-card">
                    <h2>CSS Syntax</h2>
                    <pre>{`selector {
    property: value;
}`}</pre>
                </div>

                <div className="css-card">
                    <h2>Selectors</h2>
                    <pre>{`p {
    color: red;
}

.box {
    padding: 20px;
}

#header {
    background: black;
}`}</pre>
                </div>

                <div className="css-card">
                    <h2>Colors</h2>
                    <pre>{`color: red;
background-color: blue;`}</pre>
                </div>

                <div className="css-card">
                    <h2>Font</h2>
                    <pre>{`font-size: 20px;
font-weight: bold;
font-family: Arial;`}</pre>
                </div>

                <div className="css-card">
                    <h2>Margin</h2>
                    <pre>{`margin: 20px;
margin-top: 10px;
margin-right: 15px;`}</pre>
                </div>

                <div className="css-card">
                    <h2>Padding</h2>
                    <pre>{`padding: 20px;
padding-top: 10px;
padding-bottom: 10px;`}</pre>
                </div>

                <div className="css-card">
                    <h2>Flexbox</h2>
                    <pre>{`display: flex;
justify-content: center;
align-items: center;
gap: 20px;`}</pre>
                </div>

                <div className="css-card">
                    <h2>Grid</h2>
                    <pre>{`display: grid;
grid-template-columns: repeat(3, 1fr);
gap: 20px;`}</pre>
                </div>

                <div className="css-card">
                    <h2>Position</h2>
                    <pre>{`position: relative;
position: absolute;
position: fixed;
position: sticky;`}</pre>
                </div>

                <div className="css-card">
                    <h2>Border</h2>
                    <pre>{`border: 2px solid black;
border-radius: 10px;`}</pre>
                </div>

                <div className="css-card">
                    <h2>Shadow</h2>
                    <pre>{`box-shadow: 0 5px 20px rgba(0,0,0,0.2);`}</pre>
                </div>

                <div className="css-card">
                    <h2>Responsive</h2>
                    <pre>{`@media (max-width: 768px) {
    .box {
        width: 100%;
    }
}`}</pre>
                </div>

            </div>
        </div>
    );
};

export default Css;
